"use client";

import React, { useEffect, useMemo, useState } from "react";
import { Calendar } from "@/components/ui/calendar";
import { format, parseISO, startOfWeek, endOfWeek } from "date-fns";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Plus, Trash, Edit, FileDown, ClipboardList } from "lucide-react";

// Improved MealPlanner UI using shadcn components

type MealType = "Breakfast" | "Lunch" | "Dinner" | "Snack";

type Meal = {
  id: string;
  date: string; // yyyy-MM-dd
  name: string;
  type: MealType;
  servings: number;
  calories?: number;
  ingredients: string[];
  notes?: string;
  templateOf?: string | null;
};

type Template = {
  id: string;
  name: string;
  nameOfMeal: string;
  type: MealType;
  servings: number;
  calories?: number;
  ingredients: string[];
  notes?: string;
};

const LS_MEALS = "meal-planner:meals:v1";
const LS_TEMPLATES = "meal-planner:templates:v1";
const uid = () => Math.random().toString(36).slice(2, 9);
const isoDate = (d: Date) => format(d, "yyyy-MM-dd");
const prettyDate = (iso: string) => format(parseISO(iso), "PPP");

export default function MealPlanner() {
  const [meals, setMeals] = useState<Meal[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // form state
  const [name, setName] = useState("");
  const [type, setType] = useState<MealType>("Lunch");
  const [servings, setServings] = useState<number>(1);
  const [calories, setCalories] = useState<number | "">("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [notes, setNotes] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(LS_MEALS);
      if (raw) setMeals(JSON.parse(raw));
      const rawTpl = localStorage.getItem(LS_TEMPLATES);
      if (rawTpl) setTemplates(JSON.parse(rawTpl));
    } catch (e) {
      console.error(e);
    }
  }, []);

  useEffect(() => {
    try { localStorage.setItem(LS_MEALS, JSON.stringify(meals)); } catch {}
  }, [meals]);

  useEffect(() => {
    try { localStorage.setItem(LS_TEMPLATES, JSON.stringify(templates)); } catch {}
  }, [templates]);

  const isoSelected = isoDate(selectedDate);

  const mealsForDay = useMemo(() => meals.filter((m) => m.date === isoSelected).sort((a, b) => a.type.localeCompare(b.type)), [meals, isoSelected]);

  function resetForm() {
    setName("");
    setType("Lunch");
    setServings(1);
    setCalories("");
    setIngredientsText("");
    setNotes("");
    setEditingId(null);
  }

  function addOrUpdateMeal(e?: React.FormEvent) {
    if (e) e.preventDefault();
    if (!name.trim()) return;
    const ings = ingredientsText.split("\n").map((s) => s.trim()).filter(Boolean);
    const mealObj: Omit<Meal, "id"> = {
      date: isoSelected,
      name: name.trim(),
      type,
      servings,
      calories: typeof calories === "number" ? calories : undefined,
      ingredients: ings,
      notes: notes.trim() || undefined,
      templateOf: editingId ? undefined : null,
    };

    if (editingId) setMeals((p) => p.map((m) => (m.id === editingId ? { ...m, ...mealObj } : m)));
    else setMeals((p) => [{ id: uid(), ...mealObj }, ...p]);

    resetForm();
  }

  function editMeal(meal: Meal) {
    setEditingId(meal.id);
    setName(meal.name);
    setType(meal.type);
    setServings(meal.servings);
    setCalories(meal.calories ?? "");
    setIngredientsText(meal.ingredients.join("\n"));
    setNotes(meal.notes ?? "");
    setSelectedDate(parseISO(meal.date));
  }

  function deleteMeal(id: string) {
    setMeals((p) => p.filter((m) => m.id !== id));
  }

  function saveTemplateFromForm() {
    if (!name.trim()) return;
    const newTpl: Template = {
      id: uid(),
      name: `${name.trim()} template`,
      nameOfMeal: name.trim(),
      type,
      servings,
      calories: typeof calories === "number" ? calories : undefined,
      ingredients: ingredientsText.split("\n").map((s) => s.trim()).filter(Boolean),
      notes: notes.trim() || undefined,
    };
    setTemplates((p) => [newTpl, ...p]);
  }

  function applyTemplate(tpl: Template) {
    setName(tpl.nameOfMeal);
    setType(tpl.type);
    setServings(tpl.servings);
    setCalories(tpl.calories ?? "");
    setIngredientsText(tpl.ingredients.join("\n"));
    setNotes(tpl.notes ?? "");
  }

  function aggregateGroceryList(rangeStart: Date, rangeEnd: Date) {
    const startIso = isoDate(rangeStart);
    const endIso = isoDate(rangeEnd);
    const inRange = meals.filter((m) => m.date >= startIso && m.date <= endIso);
    const items: Record<string, number> = {};
    inRange.forEach((m) => {
      m.ingredients.forEach((ing) => {
        const key = ing.toLowerCase();
        items[key] = (items[key] || 0) + 1 * (m.servings || 1);
      });
    });
    return Object.entries(items).map(([ingredient, qty]) => ({ ingredient, qty }));
  }

  function groceryForSelectedWeek() {
    const start = startOfWeek(selectedDate, { weekStartsOn: 1 });
    const end = endOfWeek(selectedDate, { weekStartsOn: 1 });
    return aggregateGroceryList(start, end);
  }

  function exportCSV() {
    const header = ["date", "name", "type", "servings", "calories", "ingredients", "notes"];
    const rows = meals.map((m) => [m.date, m.name, m.type, String(m.servings), m.calories ? String(m.calories) : "", m.ingredients.join("; "), m.notes ?? ""]);
    const csv = [header, ...rows].map((r) => r.map((cell) => { if (cell == null) return ""; const s = String(cell).replace(/"/g, '""'); return `"${s}"`; }).join(",")).join("\n") + "\n";
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `meal-planner-${format(new Date(), "yyyyMMdd")}.csv`;
    document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
  }

  const weekStart = startOfWeek(selectedDate, { weekStartsOn: 1 });
  const weekEnd = endOfWeek(selectedDate, { weekStartsOn: 1 });
  const groceryList = groceryForSelectedWeek();

  return (
    <div className="max-w-6xl mx-auto p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold">Meal Planner</h1>
          <p className="text-sm text-muted-foreground mt-1">Plan meals, save templates and build a grocery list for the week.</p>
        </div>

        <div className="flex items-center gap-2">
          <Button variant="ghost" onClick={() => { navigator.clipboard?.writeText(JSON.stringify(meals)); }} title="Export JSON">Backup</Button>
          <Button onClick={exportCSV}>
            <FileDown className="mr-2" size={16}/> Export CSV
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="p-0">
          <CardHeader className="px-4 py-3">
            <CardTitle>Calendar</CardTitle>
            <div className="text-sm text-muted-foreground">Tap a day to view / add meals</div>
          </CardHeader>
          <CardContent>
            <Calendar
              mode="single"
              selected={selectedDate}
              onSelect={(d: Date | undefined) => d && setSelectedDate(d)}
            />
            <div className="mt-3 px-1 text-sm text-muted-foreground">
              Week: {prettyDate(isoDate(weekStart))} — {prettyDate(isoDate(weekEnd))}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Add / Edit Meal — {prettyDate(isoDate(selectedDate))}</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={(e) => addOrUpdateMeal(e)} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <Input value={name} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setName(e.target.value)} placeholder="Meal name (e.g., Chicken Bowl)" />
                <div className="flex gap-2">
                  <Select onValueChange={(v: string)=>setType(v as MealType)} defaultValue={type}>
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Meal type" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Breakfast">Breakfast</SelectItem>
                      <SelectItem value="Lunch">Lunch</SelectItem>
                      <SelectItem value="Dinner">Dinner</SelectItem>
                    <SelectItem value="Snack">Snack</SelectItem>
                    </SelectContent>
                  </Select>
                  <Input type="number" value={servings} onChange={(e: React.ChangeEvent<HTMLInputElement>)=>setServings(Math.max(1, Number(e.target.value||1)))} className="w-28" />
                  <Input type="number" value={calories} onChange={(e: React.ChangeEvent<HTMLInputElement>)=>setCalories(e.target.value === "" ? "" : Number(e.target.value))} className="w-28" placeholder="cal" />
                </div>
              </div>

              <div>
                <label className="text-sm mb-1 block">Ingredients (one per line)</label>
                <Textarea value={ingredientsText} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>)=>setIngredientsText(e.target.value)} rows={4} placeholder={`e.g.\nChicken breast\nBrown rice\nBroccoli`} />
              </div>

              <div>
                <label className="text-sm mb-1 block">Notes / recipe steps (optional)</label>
                <Textarea value={notes} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>)=>setNotes(e.target.value)} rows={3} />
              </div>

              <div className="flex gap-2">
                <Button type="submit"><Plus className="mr-2" size={14}/> {editingId ? "Update Meal" : "Add Meal"}</Button>
                <Button variant="ghost" onClick={resetForm}>Clear</Button>
                <Button variant="outline" onClick={saveTemplateFromForm}>Save as Template</Button>
                <Button variant="ghost" onClick={() => navigator.clipboard?.readText().then(t=>t && setIngredientsText(txt=> txt? `${txt}\n${t}`: t)).catch(()=>{})}>Paste</Button>
              </div>
            </form>
          </CardContent>
        </Card>

        <div className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Meals — {prettyDate(isoDate(selectedDate))}</CardTitle>
            </CardHeader>
            <CardContent>
              <ScrollArea className="h-56">
                {mealsForDay.length === 0 ? (
                  <div className="text-sm text-muted-foreground">No meals planned for this day.</div>
                ) : (
                  <ul className="space-y-3">
                    {mealsForDay.map((m) => (
                      <li key={m.id} className="flex items-start justify-between gap-3">
                        <div>
                          <div className="flex items-center gap-3">
                            <span className="px-2 py-1 rounded-md bg-muted text-sm">{m.type}</span>
                            <div>
                              <div className="font-medium">{m.name}</div>
                              <div className="text-sm text-muted-foreground">{m.servings} serving(s){m.calories?` · ${m.calories} kcal`:''}</div>
                            </div>
                          </div>
                          {m.ingredients.length>0 && <div className="text-sm text-muted-foreground mt-2">Ingredients: {m.ingredients.slice(0,6).join(', ')}{m.ingredients.length>6?` +${m.ingredients.length-6} more`:''}</div>}
                          {m.notes && <div className="text-sm mt-1">{m.notes}</div>}
                        </div>

                        <div className="flex flex-col items-end gap-2">
                          <div className="flex gap-2">
                            <Button variant="ghost" size="sm" onClick={() => editMeal(m)}><Edit size={14} /></Button>
                            <Button variant="destructive" size="sm" onClick={() => deleteMeal(m.id)}><Trash size={14} /></Button>
                          </div>
                          <div className="text-xs text-muted-foreground">{m.templateOf ? "From template" : ''}</div>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </ScrollArea>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Templates</CardTitle>
            </CardHeader>
            <CardContent>
              {templates.length===0? <div className="text-sm text-muted-foreground">No templates saved yet.</div> : (
                <ul className="space-y-2">
                  {templates.map(t => (
                    <li key={t.id} className="flex items-center justify-between">
                      <div>
                        <div className="font-medium">{t.name}</div>
                        <div className="text-sm text-muted-foreground">{t.nameOfMeal} · {t.type} · {t.servings} serving(s){t.calories?` · ${t.calories} kcal`:''}</div>
                      </div>
                      <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={()=>applyTemplate(t)}>Use</Button>
                        <Button variant="destructive" size="sm" onClick={()=>setTemplates(p=>p.filter(x=>x.id!==t.id))}>Remove</Button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Grocery List — Week</CardTitle>
            </CardHeader>
            <CardContent>
              {groceryList.length===0? <div className="text-sm text-muted-foreground">No grocery items for this week.</div> : (
                <ul className="space-y-1 text-sm">
                  {groceryList.map(g => (
                    <li key={g.ingredient} className="flex justify-between"><span>{g.ingredient}</span><span className="text-muted-foreground">×{g.qty}</span></li>
                  ))}
                </ul>
              )}
            </CardContent>
            <CardFooter className="flex gap-2">
              <Button variant="ghost" onClick={() => { const text = groceryList.map(g=>`${g.ingredient} x${g.qty}`).join('\n'); navigator.clipboard?.writeText(text); }}><ClipboardList className="mr-2" size={14}/>Copy</Button>
              <Button variant="outline" onClick={() => { const html = `<html><body><h3>Grocery List</h3><ul>${groceryList.map(g=>`<li>${g.ingredient} × ${g.qty}</li>`).join('')}</ul></body></html>`; const w=window.open('', '_blank'); if(w){w.document.write(html); w.document.close();} }}>Printable</Button>
            </CardFooter>
          </Card>
        </div>
      </div>
    </div>
  );
}
